window.VPS_DATA = [
    // 1. Основное положение
    { chapter: 1, title: "1.1 - Согласие с правилами", content: "Каждый игрок после регистрации аккаунта на сервере дает свое согласие на то, что был ознакомлен со всеми правилами сервера, механизмом Role Play, а также обязуется беспрекословно их соблюдать.\n\nЭто означает, что в любом случае, независимо от ситуации или обстоятельств, Вы считаетесь ознакомленным с правилами сервера. Также Вы даете свое согласие на то, что за нарушение данных правил Вы готовы понести наказание.", punishment: "", note: "" },
    { chapter: 1, title: "1.2 - Кому подчиняются правила", content: "Внутренние Правила Сервера распространяются на всех игроков сервера, независимо от их статуса на сервере. Все игроки обязаны нести ответственность за нарушения пунктов, изложенных в данном документе.\n\nПравила сервера действуют на всех игроков, независимо от того, каким статусом или должностью игрок обладает на сервере или на других серверах проекта. Для каждого администратора сервера действуют внутренние, дополнительные правила администрации под руководством главного администратора.", punishment: "", note: "" },
    { chapter: 1, title: "1.3 - Незнание не освобождает", content: "Незнание правил не освобождает от ответственности.\n\nЭто означает, что фраза по типу «я не знал» не прокатит. Владелец аккаунта отвечает за все действия, совершенные на нем. Это значит, что причины по типу «Моя сестра сидела в это время на моем аккаунте» не являются весомыми. Таким образом, получив наказание на своем аккаунте, Вы, как его владелец, должны будете отсидеть полный срок. Это правило распространяется и на случаи, когда игрок передает компьютер другому игроку, а тот получает бан и банится серийный номер — разбаниваться серийный номер в данном случае НЕ будет.", punishment: "", note: "" },
    { chapter: 1, title: "1.4 - Администрация и презумпция", content: "Отношения между игроками и администрацией строятся на правоте администрации и презумпции невиновности игрока. Это значит, что игрок не может быть объявлен виновным, пока его вина не доказана, но и администрация не выдает наказания просто так, а действует исключительно по правилам.\n\nИгрок не может быть наказан ни по одному из пунктов, изложенных в ВПС, если его вина не доказана полностью. Администратор всегда прав. Требования администратора обязательны к выполнению, но все его действия обжалуемы на форуме. Если администратор выдал наказание неверно, Вы всегда можете подать обжалование и Вам дадут развернутый ответ, примут соответственное решение о выплате компенсации, разбане или отказе, а администратор будет нести ответственность за свои действия перед главным администратором.", punishment: "", note: "" },
    { chapter: 1, title: "1.5 - Изменение правил", content: "Администрация вправе: изменять, редактировать, дополнять правила сервера без уведомления игроков.\n\nКаждый игрок обязан следить за изменениями в данных правилах, чтобы не нарушать их на сервере.", punishment: "", note: "" },

    // 2. Игровой аккаунт
    { chapter: 2, title: "2.1 - Владелец аккаунта", content: "Владельцем игрового аккаунта является игрок, создавший его. Права владельца аккаунта не могут быть переданы другому игроку ни при каких обстоятельствах.", punishment: "", note: "" },
    { chapter: 2, title: "2.2 - Электронная почта", content: "Указывая адрес электронной почты (e-mail) во время регистрации, игрок подтверждает, что данный адрес является действующим и принадлежит только ему. В случае указания неверного адреса электронной почты, Вы автоматически теряете возможность восстановления доступа к аккаунту в экстренной ситуации. Например, если забудете пароль.\n\nВ случае, если Вы забыли пароль от аккаунта, Вам потребуется ваш e-mail адрес для его восстановления. Если по каким-то причинам владелец этого не сделал — аккаунт восстановлению не подлежит и администрация сервера вправе отказать Вам в помощи.", punishment: "", note: "" },
    { chapter: 2, title: "2.3 - Ответственность за действия", content: "Владелец аккаунта ответственен за все действия, совершенные его игровым персонажем, независимо от того, под чьим управлением находился игровой персонаж в момент совершения этих действий.", punishment: "", note: "" },
    { chapter: 2, title: "2.4 - Сохранность аккаунта", content: "Владелец аккаунта самостоятельно несет ответственность как за сохранность самого аккаунта, так и за имущество, находящееся на нем.\n\nЭто значит, что в случае взлома вся вина ложится на владельца аккаунта, ибо просто так взломать Вас никто не сможет. Вы что-то скачивали, Ваш логин светился где-то, пароль легкий, кто-то помимо Вас имеет доступ к привязанной электронной почте и т.д. При взломе аккаунта администрация в полном праве отказать Вам в помощи.", punishment: "", note: "" },
    { chapter: 2, title: "2.5 - Нелегальное имущество", content: "В случае получения игроком имущества, полученного нелегальным путем, администрация вправе его списать в полном объеме.", punishment: "", note: "" },
    { chapter: 2, title: "2.6 - Передача доступа", content: "Запрещено передавать доступ к аккаунту третьим лицам.", punishment: "Перманентный бан.", note: "По этому пункту наказывается также игрок, получивший доступ к чужому аккаунту и совершивший вход на него." },
    { chapter: 2, title: "2.7 - Взлом аккаунтов", content: "Запрещено намеренно получать доступ к аккаунту не по воле его владельца (взламывать аккаунты).", punishment: "Перманентный бан на всех серверах.", note: "Если Вам было передано имущество со взломанного аккаунта — Вы также будете наказаны по данному пункту ВПС." },
    { chapter: 2, title: "2.8 - Покупка аккаунтов", content: "Запрещено покупать аккаунты/игровую валюту в обход официального доната, а также совершать попытки этих действий, как на сервере, так и вне сервера.", punishment: "Перманентный бан.", note: "" },
    { chapter: 2, title: "2.9 - Продажа за реальные деньги", content: "Запрещено продавать, передавать, обменивать игровое имущество/вирты на реальные деньги/неигровые предметы, продавать аккаунты, а также совершать попытки этих действий, как на сервере, так и вне сервера.", punishment: "Перманентный бан на всех серверах.", note: "Исключение: дизайн форумного аккаунта, страницы ВК или канала на ютубе." },
    { chapter: 2, title: "2.10 - Обмен между серверами", content: "Запрещено обменивать игровое имущество/игровую валюту между серверами/сторонними проектами.", punishment: "Перманентный бан на серверах, где был совершен обмен.", note: "" },
    { chapter: 2, title: "2.11 - Обмен на донат", content: "Запрещено обменивать игровую валюту/игровое имущество на бонусные рубли (донат) больше, чем в ценовом соотношении х2, как на сервере, так и между серверами.", punishment: "Перманентный бан на серверах, где был совершен обмен.", note: "" },
    { chapter: 2, title: "2.12 - Обход бана", content: "Запрещено играть на аккаунте в обход наказания на другом аккаунте (обход бана).", punishment: "Удвоение наказания от изначального бана без учета срока, проведенного в бане.", note: "" },
    { chapter: 2, title: "2.13 - Вымогательство данных", content: "Запрещено вымогать/требовать у игрока данные от его игрового аккаунта (логин, пароль, e-mail), как на сервере, так и вне сервера. Доступ к аккаунту должен иметь только его владелец.", punishment: "Перманентный бан.", note: "" },
    { chapter: 2, title: "2.14 - Более 5 аккаунтов", content: "Запрещено посещать более пяти своих аккаунтов.", punishment: "Перманентный бан.", note: "" },
    { chapter: 2, title: "2.15 - Мультиаккаунтинг", content: "Запрещена одновременная игра на нескольких своих аккаунтах с разных устройств.", punishment: "Перманентный бан.", note: "Использование песочницы приравнивается к использованию стороннего ПО." },

    // 3. Игровой никнейм
    { chapter: 3, title: "3.1 - Формат никнейма", content: "Никнейм игрового персонажа должен быть написан на латинице в формате «Имя_Фамилия». Имя и фамилия пишутся с заглавной буквы. Остальные буквы — строчные. Между именем и фамилией обязательно должно быть нижнее подчеркивание «_».", punishment: "", note: "" },
    { chapter: 3, title: "3.2 - Адекватность никнейма", content: "Имя и фамилия должны быть полными, адекватными, без труда находимыми, не выделяющимися из общей массы, не слишком длинными.\n\nИмя и фамилия не должны образовывать единое словосочетание. Например: Baza_Avtonomerov, Krem_Zavarnoi и др.\nПод «адекватным» понимается никнейм, частично или всецело не обозначающий каких-либо признаков, явлений, характеристик, процессов и действий, а также непристойных, нежелательных элементов кого-/чего-либо.", punishment: "", note: "Допускается использование никнеймов, имя и фамилия которых не являются известными и без труда находимыми, при условии, что никнейм выглядит однозначно реалистично и адекватно, а имя и фамилия не похожи/не вызывают ассоциаций с краткими формами известных имен и фамилий." },
    { chapter: 3, title: "3.3 - Право администрации", content: "Администрация оставляет за собой право менять неполные имена, регистр букв в никнеймах без предупреждения игроков.", punishment: "", note: "" },
    { chapter: 3, title: "3.4 - Двойная фамилия", content: "Допускается использование двойной фамилии, с обязательным использованием нижнего подчеркивания «_» между первой и второй фамилией.", punishment: "", note: "Использование данных фамилий разрешено при условии наличия одобренной РП биографии в специальном разделе на форуме." },
    { chapter: 3, title: "3.5 - Приставки к фамилии", content: "Разрешено иметь следующие приставки к фамилиям — Mc, Mac, De, Di, La, Le, Fon, Zu, Van, Du, Al, Af, Del, Aus, Da.\n\nНапример: McDonald, McCardy, MacDonnel, MacRosson, DeRossi, DiCaprio и прочее. Все остальные запрещены.", punishment: "", note: "" },
    { chapter: 3, title: "3.6 - Смена никнейма", content: "Если никнейм игрока не соответствует правилам, и игрок еще ни разу не менял никнейм, то он вправе запросить у администрации бесплатную смену никнейма на соответствующий правилам. Если неправильный ник поставлен через донат, такое право аннулируется, и администрация вправе запросить у игрока смену никнейма на соответствующий правилам через донат.", punishment: "Требование сменить никнейм / Рандомный никнейм при игнорировании или отказе / Бан 1 день + принудительная смена ника оффлайн.", note: "" },
    { chapter: 3, title: "3.7 - Никнеймы администрации", content: "Запрещено использовать никнеймы, занятые администраторами сервера, главными администраторами других серверов, МГА, разработчиками проекта, а также похожие на них.", punishment: "Требование сменить никнейм / Рандомный никнейм при игнорировании или отказе / Бан 15 дней + принудительная смена ника оффлайн.", note: "" },
    { chapter: 3, title: "3.8 - Известные личности", content: "Запрещены никнеймы, схожие либо идентичные именам всемирно-известных политических деятелей, реальных деятелей фашизма, нацизма, членов террористических/экстремистских группировок.", punishment: "Требование сменить никнейм / Рандомный никнейм при игнорировании или отказе / Бан 1 день + принудительная смена ника оффлайн.", note: "" },
    { chapter: 3, title: "3.9 - Фейк-имена ютуберов", content: "Запрещено использовать фейк-имена известных русскоязычных «ютуберов», занятые никнеймы/похожие на них/идентичные внешне, но отличающиеся одной или несколькими буквами.", punishment: "Требование сменить никнейм / Рандомный никнейм при игнорировании или отказе / Бан 1 день + принудительная смена ника оффлайн.", note: "" },
    { chapter: 3, title: "3.10 - Нецензурные никнеймы", content: "Запрещено использование в никнейме нецензурных, оскорбительных, провокационных слов, рекламы.", punishment: "Требование сменить никнейм / Рандомный никнейм при игнорировании или отказе / Бан 30 дней + принудительная смена ника оффлайн.", note: "" },
    { chapter: 3, title: "3.11 - Похожие никнеймы", content: "Запрещено использовать никнеймы, занятые или похожие с другими игроками, в том числе используя подмену и/или дублирование букв.", punishment: "Требование сменить никнейм / Рандомный никнейм при игнорировании или отказе / Бан 1 день + принудительная смена ника оффлайн.", note: "" },
    { chapter: 3, title: "3.12 - Никнейм и скин", content: "Запрещено использовать никнейм, не соответствующий полу игрового персонажа (скину).", punishment: "Требование сменить никнейм / Рандомный никнейм при игнорировании или отказе / Бан 1 день + принудительная смена никнейма оффлайн.", note: "Возможны исключения, но только в случае, если имеется утвержденная администрацией RP-биография персонажа, в которой идет пояснение, что у мужчины преобладают женские черты, и наоборот." },

    // 4. Администрация
    { chapter: 4, title: "4.1.1 - Администратор", content: "Администратор — официальный представитель сервера, является гарантом соблюдения правил сервера игроками, оказывает помощь игрокам по игровым вопросам, не является игровым персонажем и не принимает участия в игровом процессе. Он имеет право игнорировать любой навязываемый ему RP-процесс.", punishment: "", note: "" },
    { chapter: 4, title: "4.1.2 - Ответственность администрации", content: "Администрация не несет ответственности за вылеты или перезагрузку сервера. Не имеет никакого отношения к технической части сервера, и не отвечает за нее. Не имеет никакого отношения к разработке проекта.", punishment: "", note: "" },
    { chapter: 4, title: "4.1.3 - Сохранность аккаунтов", content: "Администрация сервера не несет ответственность за сохранность аккаунтов игроков, а также имущества, закрепленного за ними. Не занимается восстановлением аккаунтов, не меняет пароли или адреса электронной почты (e-mail).", punishment: "", note: "" },
    { chapter: 4, title: "4.1.4 - Подчинение администратора", content: "Администратор подчиняется всем основным и дополнительным правилам сервера, а также внутреннему уставу администрации и его дополнениям.", punishment: "", note: "" },
    { chapter: 4, title: "4.1.5 - Отклонение от правил", content: "Администратор имеет полное право отклоняться от правил сервера и основных канонов Role Play, если это необходимо.", punishment: "", note: "" },
    { chapter: 4, title: "4.1.6 - Помехи администрации", content: "Запрещено препятствовать или создавать помехи работе администрации сервера.", punishment: "Кик / Бан на 1 день.", note: "" },
    { chapter: 4, title: "4.1.7 - Выход от наказания", content: "Запрещен выход из игры в целях избежания наказания от администрации за нарушение правил сервера.", punishment: "Удвоение наказания.", note: "" },
    { chapter: 4, title: "4.1.8 - Обман администрации", content: "Запрещено обманывать администрацию, вводить её в заблуждение.", punishment: "Бан до 30 дней.", note: "По данному пункту наказуемы все ситуации, за исключением ситуаций, которые описаны и попадают под действие пункта 10.2 ВПС." },
    { chapter: 4, title: "4.1.9 - Выбор наказания", content: "В зависимости от тяжести нарушения администратор имеет право выбрать наказание среди предложенных во внутренних правилах сервера, не превышая нормативов, прописанных в каждом пункте правил.", punishment: "", note: "" },
    { chapter: 4, title: "4.1.10 - Суммирование наказаний", content: "Если игрок нарушил несколько пунктов правил сервера, то сроки банов и меры наказаний могут суммироваться.", punishment: "", note: "" },
    { chapter: 4, title: "4.2.1 - Назначение репорта", content: "Связь с администрацией (/report) предназначается для жалоб на игроков, нарушающих каноны Role Play или правила сервера, а также для запроса помощи от администрации по теме игрового процесса. Репорт не предназначен для вопросов, ответы на которые игрок может найти самостоятельно в рамках игрового процесса.", punishment: "Предупреждение, в случае игнорирования — мут до 30 минут.", note: "Запрещено игнорировать предназначение системы связи с администрацией (offtop)." },
    { chapter: 4, title: "4.2.2 - Оскорбления в репорте", content: "Запрещено оскорбительно упоминать других игроков через репорт.", punishment: "Предупреждение / Мут до 3 часов.", note: "" },
    { chapter: 4, title: "4.2.3 - Чаты в репорте", content: "Весь 5 раздел (чаты) также распространяется и на репорт.", punishment: "", note: "" },

    // 5. Чат сервера, голосовой чат
    { chapter: 5, title: "5.1 - Metagaming (MG)", content: "«MG» Metagaming — отправка сообщений, содержащих информацию из реального мира, в игровой мир (смешивание чатов).", punishment: "Предупреждение, в случае игнорирования — мут на 30 минут.", note: "Разрешается MG в голосовом чате, если Ваш собеседник дал свое согласие на приём ООС-информации и если на момент разговора не происходит RP-ситуации." },
    { chapter: 5, title: "5.2 - Transliteration (TL)", content: "«TL» Transliteration — набор текста одного языка на другом.", punishment: "Мут на 30 минут.", note: "Пример: Vsem privet, kak dela. Запрещено кроме случаев, когда игрок живет за границей (отсутствует русская раскладка), например. Все это проверяется через панель администратора." },
    { chapter: 5, title: "5.3 - Caps Lock", content: "«Caps Lock» — написание текста в верхнем регистре.", punishment: "Мут до 1 часа.", note: "Исключение: общепринятые аббревиатуры." },
    { chapter: 5, title: "5.4 - Flood", content: "«Flood» — отправка трёх и более одинаковых сообщений подряд за короткий промежуток времени, в том числе и использование «мусорных» или засоряющих чат биндов.", punishment: "Мут на 1 час за небольшой флуд (3 и более строк) / Мут на 3 часа за сильный флуд.", note: "Сильный флуд — бесконечный «поток Вашей фантазии». Дополнение: на откат «Flood'а» дается 10 секунд. Случаются ситуации, когда у игрока залипает клавиша или происходит другая ситуация, которая вызывает данное нарушение. Администрация сможет различить намеренный флуд от случайного. Если же Вы предпримите попытку обмануть, то будете наказаны за обман администрации." },
    { chapter: 5, title: "5.5 - Flood in Voice Chat", content: "Flood in Voice Chat — крики, включение музыки/музыкальных дорожек, использование программ для изменения голоса и всё, что может помешать нормальной игре.", punishment: "Мут до 6 часов.", note: "" },
    { chapter: 5, title: "5.6 - Нецензурная лексика", content: "Чрезмерное употребление нецензурных слов и выражений.", punishment: "Предупреждение, в случае игнорирования — мут до 3 часов.", note: "Также запрещено побуждать игроков к любым действиям сексуального характера." },
    { chapter: 5, title: "5.7 - RP-команды в войсе", content: "Произношение в голосовой чат команд RP-отыгровок вместо их написания.", punishment: "Мут до 1 часа.", note: "" },
    { chapter: 5, title: "5.8 - Оскорбление игроков", content: "Оскорбление игроков.", punishment: "Предупреждение, в случае игнорирования — мут до 3 часов / Бан до 10 дней после согласования с ГА.", note: "Разрешены лёгкие оскорбления в рамках IC-процесса, если на то есть причина. Блокировка будет выдана только в том случае, если игрок оскорблениями перейдет всевозможные грани морали." },
    { chapter: 5, title: "5.9 - Spam", content: "«Spam» — реклама сторонних ресурсов, т.е. всего, что не имеет никакого отношения к проекту.", punishment: "Бан на 5555 дней после согласования с ГА.", note: "" },
    { chapter: 5, title: "5.10 - Оскорбление администрации", content: "Оскорбление администрации, разработчиков проекта.", punishment: "Мут до 5 часов / Бан до 30 дней.", note: "" },
    { chapter: 5, title: "5.11 - Неуважение к администрации", content: "Запрещено неуважительное отношение в сторону администрации.", punishment: "Мут до 3 часов.", note: "" },
    { chapter: 5, title: "5.12 - Оскорбление родственников", content: "Оскорбление родственников.", punishment: "Бан на 30 дней.", note: "Желание смерти, аббревиатура «mq» и её значение также приравнивается к оскорблению. Завуалированное оскорбление родственников также наказуемо по данному пункту." },
    { chapter: 5, title: "5.13 - Упоминание родственников", content: "Упоминание родственников в негативном контексте.", punishment: "Бан на 15 дней.", note: "Завуалированное упоминание родственника также наказуемо по данному пункту." },
    { chapter: 5, title: "5.14 - Религиозные провокации", content: "Религиозные провокации, а также оскорбления, связанные с религиозной принадлежностью игрока. Проявление ненависти в отношении политики любого правительства, политические провокации в любых проявлениях, оскорбление власти и правительства.", punishment: "Бан на 30 дней.", note: "Любое указание на символику Z и V также относится к данному пункту ВПС вне зависимости от контекста." },
    { chapter: 5, title: "5.15 - Нацизм/расизм", content: "Проявление нацизма/расизма. Запрещено проявление ненависти, основанной на расовой или национальной принадлежности игрока, если сказано кому-то в лицо или в присутствии тех, кого оскорбляют.", punishment: "Бан на 30 дней.", note: "Примеры слов, за которые последует бан: хач, хачила, чурка, хохол, русня, москаль, кацап, ниггер, гнида черножопая." },
    { chapter: 5, title: "5.16 - Угрозы вне игры", content: "Угрозы, шантаж и вымогательства по отношению к игрокам, не относящиеся к игровому (RolePlay) процессу.", punishment: "Бан до 30 дней.", note: "Угрозы блокировкой не наказываются. Пункт также распространяется на любые сторонние ресурсы (VK, Discord и т.п.), если предметом шантажа является что-либо связанное с проектом." },
    { chapter: 5, title: "5.17 - Оскорбление проекта", content: "Запрещено оскорблять проект, угрожать проекту, препятствовать его развитию, отталкивать других пользователей от приобретения каких-либо услуг.", punishment: "Бан до 30 дней.", note: "" },
    { chapter: 5, title: "5.18 - Мат на табличках", content: "Использование мата или оскорблений в информационных табличках на транспорте, а также в иных местах ввода и вывода информации в виде текста.", punishment: "Бан до 30 дней.", note: "К этому относится, например, написание подобных слов на всевозможных табличках транспорта/покрышках и т.п." },
    { chapter: 5, title: "5.19 - Реклама запрещенки", content: "Пропаганда или реклама сторонних программ/проектов, а также ресурсов по продаже игровой валюты/аккаунтов/читов/ботов/скриптов/кликеров и т.п. через информационные таблички или иные места ввода/вывода информации.", punishment: "Перманентный бан / Перманентный бан на всех серверах.", note: "" },
    { chapter: 5, title: "5.20 - Угрозы администрации", content: "Угрозы, шантаж, вымогательство и прочее в сторону администрации сервера/проекта.", punishment: "Бан до 30 дней.", note: "" },
    { chapter: 5, title: "5.21 - Неправильные RP-команды", content: "Неправильное использование команд /me /do /try /todo.", punishment: "Мут от 15 минут до 1 часа.", note: "" },
    { chapter: 5, title: "5.22 - Принудительная отыгровка", content: "Запрещена принуждающая отыгровка без согласия других сторон, намеренно эротическая отыгровка, отыгровка за другого человека.", punishment: "Бан до 5 дней.", note: "Запрещены отыгровки, не несущие в себе информационной значимости, создающие помехи в RP-ситуации." },
        { chapter: 5, title: "5.23 - Оскорбительные отыгровки", content: "Отыгрывание оскорбительных RP-ситуаций, использование оскорбительных отыгровок.", punishment: "Мут до 3 часов / Бан до 10 дней.", note: "" },

    // 6. Игровой процесс
    { chapter: 6, title: "6.1 - AFK (Away From Keyboard)", content: "«AFK» — Away From Keyboard — запрещено проявлять бездействие, отсутствие движений игрового персонажа и реакции игрока.", punishment: "Кик.", note: "Запрещён AFK в следующих случаях:\n- При онлайне свыше 800 игроков AFK разрешён до 1 минуты, а при онлайне ниже — до 15 минут.\n- Бездействие на местах спавна и/или в местах, где создаётся помеха игрокам.\n- Если Вам администратор задал вопрос «Вы тут?», то Вы обязаны ответить в репорт администратору в течение 30–40 секунд." },
    { chapter: 6, title: "6.1.1 - AFK срочной службы", content: "Запрещено находиться в «AFK» солдатам срочной службы армии, за исключением карцера.", punishment: "Бан на 1 день.", note: "" },
    { chapter: 6, title: "6.2 - BH (Bunny-Hopping)", content: "«BH» — Bunny-Hopping — NonRP бег, бег с прыжками для быстрого перемещения персонажа.", punishment: "Бан до 3 дней при пешей погоне.", note: "Наказание последует только при погоне между сотрудниками МВД/МО и преступниками." },
    { chapter: 6, title: "6.3.1 - DM (DeathMatch)", content: "«DM» — нанесение урона игровому персонажу без IC-причины.", punishment: "Бан до 3 дней.", note: "Наказание последует от 2 и более ударов. Взаимная драка не является DM." },
    { chapter: 6, title: "6.3.2 - DM через решетку", content: "«DM» — нанесение урона игровому персонажу через решетку КПЗ/карцера.", punishment: "Бан до 3 дней.", note: "Наказывается тот игрок, который наносит удары снаружи клетки. Наказание последует от 2 и более ударов." },
    { chapter: 6, title: "6.3.3 - DM Kill", content: "«DM Kill» — доведение игрового персонажа до бессознательного состояния без IC-причины. Под бессознательным состоянием подразумевается отправка игрока в больницу и полное снесение hp, после которого игрок лежит в беспомощном состоянии.", punishment: "Бан на 5 дней.", note: "К IC-причинам для подобных действий относятся: оскорбления, взаимная драка, доведение до бессознательного состояния Вашего друга/знакомого на Ваших же глазах (запрещено использовать OOC информацию в данных ситуациях), а также иные ситуации, по итогу которых логически ясно то, что игровой персонаж может быть нейтрализован. При доведении игрока до бессознательного состояния участником ОПГ, блокировка выдаётся по согласованию со следящим администратором." },
    { chapter: 6, title: "6.3.4 - DM Car", content: "«DM Car» — умышленная порча транспортных средств без IC-причины.", punishment: "Бан до 3 дней.", note: "Удары по пустому т/с будут наказуемы по пункту 6.3.4.1. Участникам официальных ПГ разрешается нанесение урона по транспорту в ситуациях, когда сотрудники стреляют из транспорта." },
    { chapter: 6, title: "6.3.4.1 - Удары по пустому ТС", content: "Умышленные удары по пустому т/с.", punishment: "Кик.", note: "" },
    { chapter: 6, title: "6.3.5 - RDM (Random DM)", content: "«RDM» — Random DM — нанесение урона/доведение двух и более персонажей до бессознательного состояния без весомой IC-причины.", punishment: "Бан до 10 дней.", note: "" },
    { chapter: 6, title: "6.4 - DB (Drive By)", content: "«DB» — Drive By — намеренное нанесение урона, доведение до бессознательного состояния другого игрового персонажа при помощи транспортного средства.", punishment: "Бан до 5 дней.", note: "По данному пункту также наказывается использование тяжелого оружия (дробовики, винтовки, автоматы) с водительского места в движении." },
    { chapter: 6, title: "6.5 - RPK (Repeat Kill)", content: "«RPK» — Repeat Kill — намеренное или повторное доведение до бессознательного состояния одного и того же игрока.", punishment: "Бан до 5 дней.", note: "Запрещено возвращаться на место нейтрализации игрока (локацию по /gps) в течение 10 минут. Если Вы убили игрока, Вы не можете ездить по карте и охотиться за ним, т.к. при отправке игрока в бессознательное состояние Ваш РП-процесс между друг другом заканчивается, и вы оба обязаны (при встрече) заново общаться так, будто ничего и не было." },
    { chapter: 6, title: "6.6 - SK (Spawn Kill)", content: "«SK» — Spawn Kill — доведение игрока до бессознательного состояния на месте появления/возрождения (Spawn).", punishment: "Бан на 5 дней.", note: "На нашем проекте места возрождения защищены зелёными зонами, поэтому нейтрализация, например, около больницы, а потом повторное доведение до бессознательного состояния того же игрока около больницы — RPK." },
    { chapter: 6, title: "6.7 - TK (Team Kill)", content: "«TK» — Team Kill — доведение до бессознательного состояния или нанесение вреда здоровью члену своей команды, фракции.", punishment: "Бан до 5 дней.", note: "В случае ТК среди фракции решение принимается следящим администратором — было это намеренно или просто являлось игровым моментом." },
    { chapter: 6, title: "6.8 - PG (Powergaming)", content: "«PG» — Powergaming — воображение игроком себя супергероем, отсутствие инстинкта самосохранения.", punishment: "Бан до 5 дней.", note: "Нереалистичное поведение, проявляющееся в отсутствии у игрового персонажа боязни за свою жизнь. Например, стрельба/драка 1 на 3 и более, проникновение/нахождение без сопровождения военнослужащих на территорию(и) ВЧ. Также драка врукопашную против игроков с огнестрельным оружием в руках. Исключения: если на игрока было наставлено оружие сотрудниками полиции/членами ОПГ, он имеет право попытаться убежать/уехать на автомобиле. При проведении мероприятий поставок патронов для ОПГ администрацией сервера участники данного мероприятия не наказываются по данному пункту." },
    { chapter: 6, title: "6.9 - WH (Wheely Hopping)", content: "«WH» — Wheely Hopping — использование бага с прыжком на велосипеде.", punishment: "Бан 1 час.", note: "" },
    { chapter: 6, title: "6.10 - NonRP", content: "«NonRP» — действия, которые невозможны в реальной жизни, нарушающие каноны RP, портящие игровую атмосферу, неоправданные, нелогичные действия.", punishment: "Бан до 5 дней.", note: "Примеры: Вы, будучи сотрудником фракции ГИБДД, лишаете прав игрока на расстоянии без каких-либо отыгровок; Вы, будучи сотрудником фракции ЦГБ, лечите пациентов, просто прописывая команду лечения без отыгровок; Вы, будучи солдатом армии, без какого-либо взаимодействия начинаете расстреливать всех игроков, приезжающих к военной части; Вы начнёте RP-взаимодействие с игроком, находящимся в AFK более 1 минуты. Запрещено RP-взаимодействие с игроками в Network Trouble; Стрельба из оружия в воздух без IC-причин; Стрельба между участниками ПГ в городах; Лечение во время боя/драки." },
    { chapter: 6, title: "6.10.1 - NonRP аксессуары", content: "NonRP использование аксессуаров. Чрезмерное увеличение/уменьшение аксессуаров, расположение их в ненадлежащих местах, в том числе с целью развлечения.", punishment: "Предупреждение, в случае игнорирования — бан на 1 час.", note: "" },
    { chapter: 6, title: "6.10.2 - NonRP-погоня", content: "«NonRP-погоня» — нереалистичная погоня.", punishment: "Бан до 10 дней.", note: "Сотрудник имеет право совершить починку/заправку после потери визуального контакта с преступником, но тогда ему запрещено продолжать погоню за игроком в течение 3 минут. Пока идёт погоня, её участникам запрещается: совершать починку/заправку Т/С; совершать намеренные срезы, а также намеренно нарушать границы дорожного полотна; уходить от погони по воде; скрываться в закрытых интерьерах; прыгать на велосипеде через заборы, крыши зданий, автомобили." },
    { chapter: 6, title: "6.11 - Выход из игры", content: "Запрещено выходить из игры во время ареста/погони/боя/похищения.", punishment: "Бан до 7 дней.", note: "Если же Вам удалось уйти от полицейской погони (не видны на радаре и в зоне прорисовки в пределах 3 минут), то Вы имеете полное право выйти из игры. Независимо от вашего положения — полицейский Вы или преступник." },
    { chapter: 6, title: "6.12 - Уход от РП", content: "Запрещено уходить от RolePlay ситуаций, отыгровок, взаимодействия с другими игровыми персонажами.", punishment: "Бан до 7 дней.", note: "Любую ситуацию Вы обязаны довести до конца, даже если ситуация складывается не в Вашу пользу. Нельзя уходить от взаимодействия с другими игровыми персонажами или делать вид, что ничего не произошло. По данному пункту также будет выдано наказание если: Один участник уходит в AFK более чем на 2 минуты; Будет совершён заезд/заход на территорию баз ПГ во время RP-ситуаций." },
    { chapter: 6, title: "6.12.1 - Систематический вылет", content: "Систематический вылет или выход из игры при RP-ситуациях (более 2-х за сутки, более 4-х за последние 7 суток).", punishment: "Бан на 21 день.", note: "" },
    { chapter: 6, title: "6.13 - Вмешательство в РП", content: "Запрещено вмешиваться в RolePlay ситуации, к которым Ваш игровой персонаж не относится. То есть бегать, прыгать, кататься вокруг игровых персонажей, участвующих в Role Play ситуации, провоцировать их, создавать помехи и портить игровую атмосферу.", punishment: "Кик / Бан до 3 дней.", note: "Например, сотрудник ЦГБ оказывает помощь игроку, а Вы подходите и нападаете на медика или убиваете игрока, с которым взаимодействовал доктор; или два игрока отыгрывают ситуацию ДТП, а Вы подъезжаете, начинаете толкать автомобиль, избивать участников ситуации." },
    { chapter: 6, title: "6.14 - Принуждение к РП", content: "Запрещено намеренно принуждать к РП игроков, в том числе для создания помех и неудобств.", punishment: "Бан до 5 дней.", note: "" },
    { chapter: 6, title: "6.15 - Провокация на нарушение", content: "Запрещена провокация игрока на нарушение внутренних правил сервера для дальнейшей подачи жалобы на него в репорт или на форум.", punishment: "Удвоенное наказание по пункту, на нарушение которого была нацелена провокация.", note: "" },
    { chapter: 6, title: "6.16 - Вызов служб", content: "Запрещено вызывать спец. службы (ГУВД, ГИБДД, ЦГБ) в труднодоступные места. Под труднодоступными местами понимаются крыши высоток, баннеры, вызовы в воздухе (с парашюта).", punishment: "Бан до 2 дней.", note: "" },
    { chapter: 6, title: "6.17 - Удержание и травля", content: "Запрещено лишать возможности передвижения игрока, насильно удерживать для ООС оскорблений, травли, угроз и запугиваний.", punishment: "Бан до 15 дней после согласования с ГА.", note: "Также под этот пункт попадает преследование с целью унижений и различных ООС оскорблений. Наказываются все участники травли/угроз и удерживания." },
    { chapter: 6, title: "6.18 - Откат действий", content: "Откаты совершенных действий не освобождают игрока от OOC-ответственности.", punishment: "", note: "Исключения: Мисклик (1 удар) по игроку/транспорту; Случайное прожатие бинда в чат с последующим откатом." },
    { chapter: 6, title: "6.19 - Помехи персонажем", content: "Запрещено намеренно создавать помехи другим игрокам своим игровым персонажем.", punishment: "Предупреждение, в случае игнорирования: перекрытие мелкого проезда — кик / перекрытие крупных проездов — бан до 1 дня.", note: "Перекрытие проездов, проходов, дорог и всё то, что может помешать нормальному перемещению других игроков." },

    // 7. Правила дорожного движения (ВПС)
    { chapter: 7, title: "7.1.1 - Светофоры", content: "Светофоры в ночной режим переводятся в 00:00 по МСК, в обычный режим переводятся в 12:00 по МСК.", punishment: "", note: "" },
    { chapter: 7, title: "7.1.2 - Намеренный таран", content: "Намеренный таран — намеренное нанесение урона имуществу игроков транспортным средством.", punishment: "Бан до 7 дней.", note: "Исключения: Разрешено толкать на своем личном автомобиле личный автомобиль другого игрока, который полностью выведен из строя, на малой скорости до ближайшего маркера починки, если нет механиков в игре. Сотрудникам МВД разрешено совершать спец. маневры для остановки нарушителя." },
    { chapter: 7, title: "7.1.3 - Массовый таран", content: "Намеренный массовый таран — намеренное нанесение урона имуществу нескольких игроков транспортным средством.", punishment: "Бан до 10 дней.", note: "" },
    { chapter: 7, title: "7.1.4 - Подрезы", content: "Запрещены специальные подрезы других участников дорожного движения, намеренное создание аварийных ситуаций, дабы остановить других участников дорожного движения.", punishment: "Бан до 3 дней.", note: "Исключение: сотрудникам МВД/МО разрешено совершать спец. маневры для остановки нарушителя." },
    { chapter: 7, title: "7.1.5 - Подрезы по пингу", content: "Намеренные подрезы по пингу.", punishment: "Бан до 7 дней.", note: "" },
    { chapter: 7, title: "7.1.6 - Массовые подрезы по пингу", content: "Массовые намеренные подрезы по пингу.", punishment: "Бан до 10 дней.", note: "" },
    { chapter: 7, title: "7.1.7 - Бездорожье", content: "Запрещена езда по бездорожью, рельсам на не предназначенных для этого автомобилях.", punishment: "Тюрьма на 30 минут.", note: "Скорость движения по полям/рельсам на предназначенных для этого автомобилях разрешена со скоростью не более 60 км/ч. Исключение: разрешено выезжать с поля со скоростью до 10 км/ч при случайном вылете с дороги." },
    { chapter: 7, title: "7.1.8 - Езда по рельсам", content: "Запрещена продолжительная езда по рельсам на соответствующем автомобиле.", punishment: "Тюрьма на 30 минут.", note: "Разрешено переехать через рельсы, которые находятся вне крупных городов (Приволжск, Мирный, Невский) на транспорте, на котором разрешена езда по рельсам, и со скоростью не более 60 км/ч, но не ехать по ним. Исключение: сотрудникам РЖД разрешена продолжительная езда по рельсам на фракционном транспорте при совершении работ на путях." },
    { chapter: 7, title: "7.1.9 - Срезы и тротуары", content: "Запрещены срезы, намеренная езда по тротуару и намеренное нарушение границ дорожного полотна.", punishment: "Тюрьма на 30 минут.", note: "Исключениями являются случаи, разрешенные ПДД Провинции, заезды во дворы и дворовые территории города Невский, а также заезды на системные маркеры, располагающиеся на тротуарах/газонах: Маркеры на территории ТК Приволжска; Маркер для такси около тира Невского; Маркеры СТО." },
    { chapter: 7, title: "7.1.10 - Помехи транспортом", content: "Запрещено создание при помощи транспорта помех или неудобств другим игрокам.", punishment: "Перекрытие мелкого проезда — кик / перекрытие крупных проездов, загораживание маркеров, огромные помехи — бан до 5 дней.", note: "Перекрытие различных въездов/выездов, стоянка на пешеходных маркерах, блокировка трамвайного движения также наказуема." },
    { chapter: 7, title: "7.1.11 - Встречка", content: "Запрещена намеренная езда по встречке. По данному пункту также наказывается движение задним ходом в нарушение ПДД.", punishment: "Тюрьма на 30 минут.", note: "Исключение: уход от полицейской погони, а также случаи, разрешенные ПДД Провинции. Если Вы потеряли управление и выскочили на встречную полосу — Вы должны немедленно вернуться на свою полосу или полностью остановить автомобиль. Дальнейшее движение наказывается." },
    { chapter: 7, title: "7.1.12 - Взлетная полоса", content: "Запрещена езда по взлетной полосе.", punishment: "Тюрьма на 60 минут.", note: "" },
    { chapter: 7, title: "7.1.13 - Тест тюнинга", content: "Правила, касающиеся теста пакетов тюнинга и транспорта в автосалоне.", punishment: "", note: "Участникам можно тараниться/подрезать друг друга (если у них на номерах слово «тест»); Запрещено подрезать игроков на ЛТС (Бан на 5 часов); Запрещено таранить игроков на ЛТС (Бан на 3 дня); Разрешена езда по полям; Разрешено не отыгрывать ДТП; Остальные пункты ВПС при тесте свою силу не теряют; Разрешено нарушать ПДД." },
    { chapter: 7, title: "7.2.1 - Объезд светофора", content: "Запрещено ездить по дворам, через стоянки торговых центров или проезжать через автостанцию или заправку, с целью объехать светофор или сократить себе путь.", punishment: "Тюрьма на 30 минут.", note: "" },
    { chapter: 7, title: "7.2.2 - Личное использование", content: "Запрещено использовать рабочий транспорт в личных целях.", punishment: "Лишение прав на 14 дней / Бан на 2 дня.", note: "" },
    { chapter: 7, title: "7.2.3 - Удержание пассажира", content: "Намеренное удержание пассажира в транспорте.", punishment: "Бан на 12 часов.", note: "" },
    { chapter: 7, title: "7.2.4 - Открытые двери", content: "Запрещена езда с открытыми дверьми.", punishment: "Предупреждение, в случае игнорирования — кик.", note: "" },
    { chapter: 7, title: "7.2.5 - Фары и свет", content: "Езда без включенных фар и/или света в салоне.", punishment: "Предупреждение, в случае игнорирования — кик.", note: "Свет в салоне должен быть включен с 18:00 до 6:00 по игровому времени." },
    { chapter: 7, title: "7.2.6 - AFK на транспорте", content: "Запрещен AFK на общественном транспорте вне конечной остановки, а также на рабочем транспорте более 3 минут (кроме рельсового транспорта).", punishment: "Кик.", note: "" },
    { chapter: 7, title: "7.2.7 - Продажа транспорта", content: "Запрещено продавать рабочий транспорт.", punishment: "Бан на 15 дней.", note: "" },
    { chapter: 7, title: "7.2.8 - Требование оплаты", content: "Требования с пассажиров оплаты какой-либо услуги.", punishment: "Лишение прав на 14 дней / Бан на 5 дней.", note: "Если водитель такси работает на своем автомобиле, то такие жалобы рассматриваются только через форум, где виден вызов такси и т.п." },
    { chapter: 7, title: "7.2.9 - Очередность", content: "Запрещено игнорировать очередность при подъезде к остановке.", punishment: "Лишение прав на 14 дней.", note: "" },
    { chapter: 7, title: "7.3.1 - Обгон троллейбуса", content: "Обгон впереди идущего троллейбуса, у которого подняты штанги.", punishment: "Лишение прав на 14 дней / Бан на 1 день.", note: "Исключение: обгон троллейбусов с поднятыми штангами, если те не заняты другими игроками." },
    { chapter: 7, title: "7.3.2 - Игра штангами", content: "Игра штанговыми токоприёмниками. Пример: обгон впереди идущего троллейбуса при помощи разгона, опускание штанг и их поднятие.", punishment: "Лишение прав на 14 дней.", note: "" },
    { chapter: 7, title: "7.3.3 - Дистанция", content: "Несоблюдение дистанции между троллейбусами.", punishment: "Предупреждение, в случае игнорирования — переобучение.", note: "" },
    { chapter: 7, title: "7.3.4 - Задний ход", content: "Умышленно двигаться задним ходом.", punishment: "Предупреждение, в случае игнорирования — лишение прав на 14 дней.", note: "" },
    { chapter: 7, title: "7.3.5 - AFK троллейбус", content: "Запрещен AFK вне конечной остановки/на маршруте с поднятыми штанговыми токоприемниками.", punishment: "Кик.", note: "" },
    { chapter: 7, title: "7.4.1 - Медленная езда", content: "Запрещено умышленное движение с малой скоростью, создающее помехи другим игрокам.", punishment: "Предупреждение, в случае игнорирования — переобучение / Бан на 12 часов.", note: "" },
    { chapter: 7, title: "7.4.2 - Задний ход (рельсы)", content: "Запрещено движение задним ходом.", punishment: "Лишение прав на 14 дней / Переобучение в случае с поездом метро.", note: "" },
    { chapter: 7, title: "7.4.3 - AFK в трамвае", content: "Запрещено нахождение в AFK на маршруте в трамвае. Разрешено находиться в AFK только в трамвайном депо (не более 3 минут).", punishment: "Кик.", note: "" },
    { chapter: 7, title: "7.4.4 - Двери (рельсы)", content: "Запрещена езда с открытыми дверьми.", punishment: "Предупреждение, в случае игнорирования — переобучение.", note: "" },
    { chapter: 7, title: "7.4.5 - Дистанция (рельсы)", content: "Запрещено не соблюдать дистанцию.", punishment: "Предупреждение, в случае игнорирования — переобучение.", note: "Минимальная дистанция — два вагона." },
    { chapter: 7, title: "7.4.6 - Анти-сквозь", content: "Умышленное торможение системой анти-сквозь.", punishment: "Переобучение.", note: "" },
    { chapter: 7, title: "7.4.7 - Торможение пантографом", content: "Торможение пантографом.", punishment: "Лишение прав на 14 дней.", note: "" },
    { chapter: 7, title: "7.4.8 - Проезд сквозь транспорт", content: "Запрещено проезжать сквозь впереди или сзади идущий трамвай/поезд.", punishment: "Лишение прав на 14 дней в случае с трамваем / Переобучение в случае с поездом метро.", note: "Исключение: разрешен проезд сквозь пустой трамвай. Разрешен проезд сквозь занятый трамвай в трамвайном депо." },
    { chapter: 7, title: "7.5.1 - Отклонение от маршрута", content: "Запрещено отклоняться от маршрута (водный транспорт).", punishment: "Бан на 2 часа.", note: "" },
    { chapter: 7, title: "7.5.2 - Скорость катера", content: "Запрещено перемещаться слишком быстро на прогулочном катере, не давая экскурсоводу закончить речь.", punishment: "Предупреждение, в случае игнорирования — кик.", note: "" },
    { chapter: 7, title: "7.5.3 - Теплоход", content: "Запрещено запрыгивать на движущийся теплоход, создавая помеху капитану.", punishment: "Кик.", note: "" },
    { chapter: 7, title: "7.5.4 - Урон теплоходу", content: "Запрещено намеренно наносить урон теплоходу или прогулочному катеру.", punishment: "Бан до 5 дней.", note: "" },
    { chapter: 7, title: "7.6.1 - Спам эвакуатора", content: "Запрещено предлагать ремонт всем подряд или предлагать эвакуацию, то есть спамить запросами.", punishment: "Невозможно наказать в онлайн-режиме / Бан на 5 дней.", note: "" },
    { chapter: 7, title: "7.6.2 - Мешать эвакуатору", content: "Мешать выполнять заказ другому водителю-механику эвакуатора.", punishment: "Предупреждение, в случае игнорирования — кик.", note: "" },
    { chapter: 7, title: "7.7.1 - Уничтожение инкассации", content: "Запрещено умышленно уничтожать сотрудникам инкассации грузовик с целью обогащения.", punishment: "Бан на 60 дней каждому члену экипажа.", note: "Любой сговор в отношении работы и получении денег. Это и любой сговор по навариванию через ограбления, это и намеренные взрывы, чтобы потом забрать сумки." },
    { chapter: 7, title: "7.7.2 - AFK инкассатор", content: "Запрещено находиться в AFK (инкассатор).", punishment: "Бан на 12 часов.", note: "Если Вы начинаете работу на инкассаторах и бригада уже сформирована (Вам уже присвоена какая-либо роль), то забудьте об АФК на все время работы." },
    { chapter: 7, title: "7.7.3 - Оружие инкассатора", content: "Запрещено использование оружия не по назначению.", punishment: "Бан на 10 дней.", note: "Разрешено использовать оружие только в случае нападения на экипаж, либо же в случае обороны во время ограбления." },
    { chapter: 7, title: "7.7.4 - Форма инкассатора", content: "Запрещено использовать форму инкассации в личных целях.", punishment: "Бан на 1 день.", note: "Если Вы переоделись в форму инкассации, то не покидайте интерьер банка и гаража ни при каких-либо обстоятельствах." },
    { chapter: 7, title: "7.7.5 - Сбив анимации", content: "Намеренный сбив анимации (инкассация).", punishment: "Бан на 1 день.", note: "" },
    { chapter: 7, title: "7.7.6 - Выход из игры (инкассация)", content: "Намеренный выход из игры во время работы инкассатором или выход водителя из автомобиля, а также умышленное расформирование бригады, убегая от автомобиля и т.п.", punishment: "Бан на 3 дня.", note: "Если у Вас произошел вылет, то обязательно соберите все доказательства вылета для обжалования на форуме, если будет выдано наказание по этому пункту." },
    { chapter: 7, title: "7.7.7 - Ограбление инкассации", content: "Запрещено нарушать общие правила ограбления инкассации.", punishment: "Бан на 15 дней за любое нарушение общих правил ограбления инкассации.", note: "" },
    { chapter: 7, title: "7.7.8 - Высадка из авто", content: "Запрещено водителю инкассации на автостоянке в интерьере банка, во время формирования бригады, намеренно высаживать из автомобиля других участников.", punishment: "Невозможно наказать в онлайн-режиме / Бан на 1 день.", note: "" },
    { chapter: 7, title: "7.7.9 - Рецидив (инкассация)", content: "Рецидив деструктивного поведения и игнорирование наказаний по ранним нарушениям во время работы инкассатором.", punishment: "Удвоенное наказание от изначального по согласованию с ГА сервера.", note: "" },

    // 8. Мошенничество
        { chapter: 8, title: "8.1 - Малые махинации", content: "Запрещены любые денежные махинации, развод игроков на малые суммы денег (до 100 000 рублей).", punishment: "Бан до 60 дней.", note: "" },
    { chapter: 8, title: "8.2 - Крупные махинации", content: "Запрещены любые денежные махинации, развод игроков на имущество/большие суммы денег (от 100 000 рублей).", punishment: "Перманентный бан на всех серверах.", note: "" },
    { chapter: 8, title: "8.3 - Обман при сделках", content: "Запрещены любые попытки обмана игроков, попытки ловли на невнимательность, скрытие каких-либо подробностей/особенностей продаваемого игрового имущества.", punishment: "Перманентный бан.", note: "Сделки, где договор идет на одну цену или на один вид имущества, а на деле кидается совсем иное предложение с менее выгодными, обманывающими условиями." },
    { chapter: 8, title: "8.4 - Спам запросами", content: "Запрещено спамить запросами о продаже какого-либо имущества (2+).", punishment: "Перманентный бан.", note: "Наказание идет от двух и более предложений покупки." },
    { chapter: 8, title: "8.5 - Невозврат долгов", content: "Запрещено занимать средства/имущество и не возвращать их в срок.", punishment: "Перманентный бан.", note: "Условия данных сделок должны быть проговорены непосредственно в игре, т.е. доказательства предоставлены должны быть тоже из игры." },
    { chapter: 8, title: "8.6 - Финансовые услуги", content: "Запрещены все виды банковских/букмекерских/страховых услуг, финансовые пирамиды, проведение крупных лотерей с целью материальной выгоды, без разрешения главного администратора.", punishment: "Перманентный бан.", note: "Разрешение на работу таких услуг регулирует главный администратор сервера." },

    // 9. Использование сторонних программ и недоработок
    { chapter: 9, title: "9.1 - Читы и скрипты", content: "Запрещено использование любых программ, скриптов, читов, ботов, дающих нечестное преимущество в игре.", punishment: "Перманентный бан на всех серверах.", note: "" },
    { chapter: 9, title: "9.2 - Фейковые лаги", content: "Запрещено создание «фейковых» лагов. К этому относится намеренное снижение ФПС и создание искусственных подергиваний.", punishment: "Перманентный бан на всех серверах.", note: "" },
    { chapter: 9, title: "9.3 - Боты для работ", content: "Запрещено использование любых программ, скриптов, ботов для работ.", punishment: "Перманентный бан.", note: "" },
    { chapter: 9, title: "9.4 - Крупные баги", content: "Запрещено использование крупных багов, ошибок, недоработок игрового мода в личных целях, а также в целях получения преимущества или обогащения.", punishment: "Бан до перманентного на всех серверах после согласования с ГА.", note: "" },
    { chapter: 9, title: "9.5 - Мелкие баги", content: "Запрещено использование мелких багов, ошибок, недоработок игрового мода в личных целях, а также ради развлечения.", punishment: "Бан до 30 дней.", note: "Злоупотребление игровыми механиками с целью вредительства наказывается по этому же пункту. Например, езда под водой, прыжки/ускорение с круиз-контролем, торможение с использованием ручника через транспортную панель (F3), флуд в чат с целью вредительства." },
    { chapter: 9, title: "9.6 - Обход Анти-АФК", content: "Запрещён обход Анти-АФК системы, АФК-боты.", punishment: "Бан на 1 день.", note: "Например: игрок, который зажимает клавишу W и, упершись в стенку, радостно бежит вперёд, тем самым создавая иллюзию того, что он не в АФК." },
    { chapter: 9, title: "9.7 - Ловля бизнеса", content: "Создание помех ловле бизнеса или недвижимости путём флуда отыгровками, командами, вызывающими появление диалоговых окон.", punishment: "Бан на 30 дней.", note: "" },

    // 10. Действия вне игры
    { chapter: 10, title: "10.1 - Удаление доказательств", content: "Удаление или редактирование доказательств из жалобы на форуме.", punishment: "Бан до 15 дней.", note: "Доказательства Вы обязаны держать неизменными на протяжении 10 суток с момента подачи жалобы на форум. Разрешается удаление, если: В рассмотрении жалобы отказано администрацией; По результатам рассмотрения никто не был наказан; Жалоба не была рассмотрена администрацией." },
    { chapter: 10, title: "10.2 - Обман на форуме", content: "Обман администрации на форуме и ввод её в заблуждение.", punishment: "Бан до 30 дней.", note: "Например: подделывание доказательств в жалобах на игроков, вследствие которых игрок или администратор могут быть незаслуженно наказаны, либо вовсе уйдут от наказания." },
    { chapter: 10, title: "10.3 - Фейковый админ", content: "Представление себя в качестве администратора или разработчика проекта на сервере, форуме, VK, Discord и других соц. ресурсах.", punishment: "Бан до 5555 дней.", note: "Пример: Вы назвали страницу в ВК ником админа и вымогаете деньги за разбан." },
    { chapter: 10, title: "10.4 - Слив информации", content: "Лидерам запрещено распространять информацию, которая публикуется следящей администрацией/ГА в беседах/группах, в которых установлен особый статус.", punishment: "Выговор / Увольнение из организации / Бан до 5555 дней после согласования с ГА.", note: "Бан сотрудникам выдается только в случае слива/удаления фракционных таблиц/бесед/групп, слива панели «ю» или слива в /gov, злоупотребления служебными возможностями. Запрещено распространение информации с обзвона." },
    { chapter: 10, title: "10.5 - Реклама деструктива", content: "Запрещено рекламировать/продавать что-либо, деструктивно влияющее на проект (читы, боты, прокачки аккаунтов, продавцов валюты, аккаунтов и т.д.).", punishment: "Перманентный бан на всех серверах.", note: "Также запрещена любая темная деятельность: переписка, общение, дискуссия, где Вы пытаетесь/договариваетесь купить/продать виртуальные игровые деньги или ресурсы за реальные деньги или читы." },
    { chapter: 10, title: "10.6 - Слив багов", content: "Запрещено распространять любую информацию о недоработках, багах для нечестного обогащения или наживы на этом.", punishment: "Перманентный бан.", note: "Разрешено передавать подобную информацию только управляющему составу администрации сервера или же разработчикам проекта." },
    { chapter: 10, title: "10.7 - Конфиденциальная информация", content: "Запрещено распространять (сливать, пересылать, рассказывать) информацию, которая является конфиденциальной и не подлежит распространению третьим лицам.", punishment: "Бан до перманентного.", note: "Примеры: информация с обзвонов на посты администратора, лидера, заместителя. Информация с конференций, на которых есть особый статус." },

    // 11. Дополнительные правила
    { chapter: 11, title: "11.1 - Действия ОПГ", content: "Запрещены действия, разрешенные и присущие лишь организованным преступным группировкам (похищения игроков, участие в массовых беспорядках, крупные вооруженные конфликты с полицией) со стороны игроков, не состоящих в них.", punishment: "Бан на 30 дней.", note: "Все зарегистрированные ПГ должны соблюдать предписанные им правила. Запрещено заниматься какой-либо преступной деятельностью, а также участвовать в каких-либо стрелках и т.п. с официальными ПГ и семьями или заниматься проведением «тренировок». Исключение: в рамках глобальных РП ситуаций возможны отступления от данного пункта по согласованию с ГА." },
    { chapter: 11, title: "11.2 - Лаги и пинг", content: "Лаги, подергивания, резкие перемещения Вашего игрового персонажа, которые создают помехи другим игрокам (высокий ping, низкий fps в игре, слабое интернет-соединение).", punishment: "Кик.", note: "" },
    { chapter: 11, title: "11.3 - Вредительские видео", content: "Создание видеороликов, содержание которых сводится к массовому вредительству, нанесению урона и нарушению всех возможных правил сервера.", punishment: "Перманентный бан аккаунта после согласования с ГА.", note: "" },
    { chapter: 11, title: "11.4 - Долгая авторизация", content: "Продолжительная авторизация (вход) на сервер при количестве игроков на сервере выше 800.", punishment: "Кик.", note: "Правило начинает действовать при достижении онлайна (на сервере) в 800 человек. На авторизацию Вам дается 2 минуты." },
    { chapter: 11, title: "11.5 - Содействие читерам", content: "Запрещено содействие, прикрывательство, подстрекательство читеров.", punishment: "Бан на 60 дней после согласования с ГА.", note: "Под данным пунктом имеется в виду различная помощь читерам. Например, совместная игра с читерами, обладание информацией о читерах и умалчивание, предоставление своего транспорта." },
    { chapter: 11, title: "11.6 - Стримснайп", content: "«Стримснайп» — запрещено создавать помехи, направленные на намеренное вредительство ведущему стрима и его аудитории.", punishment: "Бан 30 дней.", note: "Сюда входит намеренное преследование с целью создания помех, поиск игрока при помощи стрима в различных РП ситуациях и прочее." },
    { chapter: 11, title: "11.7 - Доксинг", content: "«Доксинг» — запрещено распространять или публиковать личную информацию других игроков без их согласия на сервере, форуме, VK, Discord и других соц. ресурсах.", punishment: "Бан до перманентного после согласования с ГА.", note: "Сюда относится: адрес, номер телефона, фотографии, IP-адрес, место работы/учёбы и любые другие персональные данные, включая данные родственников игрока. Угрозы сливом информации также считаются нарушением." }
];